// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: make this test contract the DAO (so we can call setGoverned)
        // First, configure flash governance parameters via onlySuccessfulProposal
        // Need to make ourselves a successful proposal - we are DAO, but configured is false initially
        // So assertSuccessfulProposal will pass because !configured

        // Configure flash governance asset (use a mock ERC20)
        // We'll deploy a simple ERC20 for testing
        address asset = address(new MockERC20());
        // Give the contract some allowance to transfer from us
        MockERC20(asset).approve(address(c), 100 ether);

        // Configure via onlySuccessfulProposal - works since configured is false
        c.configureFlashGovernance(asset, 100 ether, 1000, false);

        // Configure security params
        c.configureSecurityParameters(10, 7 days, 50);

        // Mark another address as governed (we'll use address(0x1234) as governed caller)
        address[] memory govs = new address[](1);
        govs[0] = address(0x1234);
        bool[] memory isGov = new bool[](1);
        isGov[0] = true;
        c.setGoverned(govs, isGov);

        // Now, set up a pending flash decision for target=address(this), sender=address(0x1234)
        // with unlockTime in the past (so it's expired)
        // We do this by calling as governed address to trigger the LOGIC in assertGovernanceApproved
        // First, warp to a time after the current unlockTime
        // We need the asset transfer to succeed, but then the second call will have pendingDecision

        // First call: transferFrom will succeed (we gave allowance), pendingDecision will be created
        vm.warp(0);
        vm.prank(address(0x1234));
        bool firstOk;
        try c.assertGovernanceApproved(0x1234, address(this), false) {
            firstOk = true;
        } catch {
            firstOk = false;
        }
        // Reference: first call succeeds (transfer happens, pending created)
        // Warp past unlockTime
        vm.warp(2000);

        // Now second call with same sender/target - pendingDecision exists and is expired
        // But we will NOT transfer any tokens (we have no allowance again)
        // In reference: requires BOTH transferFrom AND pending decision expired -> will revert (transfer fails)
        // In buggy (OR): only requires one -> pending decision expired is enough -> succeeds

        bool ok;
        vm.prank(address(0x1234));
        try c.assertGovernanceApproved(address(0x1234), address(this), false) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok is false (reverts because transfer fails)
        // Buggy: ok is true (because OR condition)
        assertTrue(!ok);
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        balanceOf[address(this)] = type(uint256).max;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount, "no allowance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

