pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set DAO to a non-zero address so assertSuccessfulProposal checks pass (configured false)
        c.setDAO(address(0xdead));
        // Set flashGovernanceConfig.asset to a token that will reject transferFrom (e.g. zero address)
        // We'll set the asset to address(0) so transferFrom returns false
        // We need a successful proposal to configure, but we can use a trick: since configured is false,
        // onlySuccessfulProposal will skip the check because assertSuccessfulProposal allows when !configured.
        c.configureFlashGovernance(address(0), 100, 3600, false);
        // Now caller is not DAO and not governed, but flashEnabled requires msg.sender == DAO || governed[msg.sender]
        // We'll set governed[address(this)] = true via setGoverned after a successful proposal? No, simpler:
        // Actually we are the DAO in setUp (we deployed from this contract). But we changed DAO to 0xdead.
        // Let's use vm.startPrank to impersonate a governed user: we need to set governed first.
        // To set governed we need onlySuccessfulProposal which requires !configured || successfulProposal.
        // configured is false, so it passes. Let's set governed[address(0x123)] = true
        address user = address(0x123);
        address[] memory govs = new address[](1);
        govs[0] = user;
        bool[] memory govsBool = new bool[](1);
        govsBool[0] = true;
        c.setGoverned(govs, govsBool);
        // Now prank as user (governed)
        vm.startPrank(user);
        // The reference requires transferFrom returns true AND unlockTime < block.timestamp (both true)
        // Since asset is address(0), transferFrom will revert (or return false depending on impl).
        // In the reference, with &&, if transferFrom returns false, the whole if fails => revert.
        // In the bug version with ||, even if transferFrom fails (returns false), the second condition
        // `pendingFlashDecision[target][sender].unlockTime < block.timestamp` is true (default 0 < block.timestamp)
        // So the bug version proceeds, sets pendingFlashDecision and emits flashDecision.
        // We'll call assertGovernanceApproved with arbitrary target and emergency=false.
        // We need to catch the revert on the reference: it reverts with "LIMBO: governance decision rejected."
        bool ok;
        try c.assertGovernanceApproved(user, address(0xabc), false) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        // In the reference, ok = false (revert). In the bug version, ok = true (no revert).
        // But we need an assertion that ref holds and bug breaks. Let's check a state change:
        // In the bug version, pendingFlashDecision[target][user].unlockTime gets set to block.timestamp + unlockTime
        // In the reference, it remains 0. We can read unlockTime via getter.
        // Actually unlockTime is inside FlashGovernanceConfig struct, which has an auto-generated getter.
        // The mapping is pendingFlashDecision(target)(user) returns (amount, unlockTime, asset, assetBurnable)
        (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable) = c.pendingFlashDecision(address(0xabc), user);
        // In reference, unlockTime should be 0 because the call reverted and didn't update.
        // In bug version, unlockTime = block.timestamp + 3600 (which is > 0).
        // Reference holds: assertTrue(unlockTime == 0) is true.
        // Bug breaks: unlockTime != 0, so assertTrue(unlockTime == 0) fails.
        assertTrue(unlockTime == 0);
    }
}

